package com.ecommerce.controller;
import com.ecommerce.dto.*; import com.ecommerce.service.PedidoService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/pedidos") public class PedidoController {private final PedidoService s;public PedidoController(PedidoService s){this.s=s;} @PostMapping("/confirmar") public ResponseEntity<PedidoResponse> confirmar(@AuthenticationPrincipal UserDetails u){return ResponseEntity.ok(s.confirmarPedido(u.getUsername()));} @GetMapping("/mis-pedidos") public ResponseEntity<List<PedidoResponse>> mis(@AuthenticationPrincipal UserDetails u){return ResponseEntity.ok(s.listarPedidosUsuario(u.getUsername()));} @GetMapping("/mis-pedidos/{id}") public ResponseEntity<PedidoResponse> uno(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){return ResponseEntity.ok(s.obtenerPedidoUsuario(u.getUsername(),id));} @GetMapping("/todos") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<List<PedidoResponse>> todos(){return ResponseEntity.ok(s.listarTodosLosPedidos());} @GetMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<PedidoResponse> admin(@PathVariable Long id){return ResponseEntity.ok(s.obtenerPedido(id));} @PutMapping("/{id}/estado") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<PedidoResponse> estado(@PathVariable Long id,@Valid @RequestBody ActualizarEstadoPedidoRequest r){return ResponseEntity.ok(s.actualizarEstado(id,r));}}
